To solve this problem, you need to implement a **Global Tooltip Provider**.

Since Next.js components are isolated, you cannot rely on local state (like `useState` inside the component) to track which tooltip is open. Instead, you will use **React Context** to create a single source of truth for the "active" tooltip ID across the entire application.

Here is the complete implementation.

### 1. Create the Context Provider
This component manages the state of the currently active tooltip. It exposes a function to open a tooltip and a function to close it.

```tsx
// components/tooltip/tooltip-provider.tsx
'use client'; // Required for client-side interactivity

import React, { createContext, useContext, useState, ReactNode } from 'react';

interface TooltipContextType {
  openTooltip: (id: string) => void;
  closeTooltip: () => void;
  isOpen: boolean;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider = ({ children }: { children: ReactNode }) => {
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);

  const openTooltip = (id: string) => {
    // If a tooltip is already open, close it first (optional, but good for UX)
    setActiveTooltipId(id);
  };

  const closeTooltip = () => {
    setActiveTooltipId(null);
  };

  const isOpen = activeTooltipId !== null;

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip, isOpen }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

