Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we shift the `id` and `size` into their specific bit positions within a 7-bit integer (0-6). We then write this integer into the `Uint8Array` at the current offset.
2.  **Unpacking**: We iterate through the `Uint8Array`. For each byte, we extract the lower 4 bits for the `id` and the upper 3 bits for the `size`.

### JavaScript Code

```javascript
/**
 * Packs an array of entities into a Uint8Array.
 * 
 * @param {Array} entities - Array of objects with {id, size}
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
    if (!entities || entities.length === 0) {
        return new Uint8Array(0);
    }

    // Calculate total bytes needed: 1 byte per entity
    const totalBytes = entities.length;
    const buffer = new Uint8Array(totalBytes);

    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];

        // Ensure data is within bounds (id: 0-15, size: 0-7)
        // This prevents shifting errors if input data is invalid
        const id = entity.id & 0x0F;      // Mask to 4 bits
        const size = entity.size & 0x07;   // Mask to 3 bits

        // Combine into a single 7-bit integer
        // (size << 4) | id
        const packedValue = (size << 4) | id;

        buffer[i] = packedValue;
    }

    return buffer;
}

/**
 * Unpacks a Uint8Array into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with {id, size}
 */
function unpackEntities(buffer) {
    const entities = [];

    for (let i = 0; i < buffer.length; i++) {
        const byte = buffer[i];

        // Extract fields
        const id = byte & 0x0F;       // Lower 4 bits
        const size = (byte >> 4) & 0x07; // Upper 3 bits

        entities.push({ id, size });
    }

    return entities;
}

// --- Example Usage ---

const inputEntities = [
    { id: 1, size: 2 },
    { id: 15, size: 7 },
    { id: 0, size: 0 }
];

