    // 1. Prepare Request
    Message request = createMessage(MESSAGE_MAGIC, 0, 0, 0, CS_REQUEST);
    Info new_info;
    new_info.time = time_clock;
    new_info.id = id;
    push(new_info);

    // 2. Broadcast Request
    send_multicast(&id, &request);

    // 3. Wait for all replies
    while (!entered_mutex()) {
        Message received;
        local_id from = get(&received);

        if (from > 0) {
            handle_message(received, from);
        }
    }

    return 0;
}

int release_cs(const void *self) {
